import type { A1Module, Lesson } from "@/lib/course";

type PhraseSeed = [english: string, portuguese: string, note: string];
type ExampleSeed = [english: string, portuguese: string];
type QuestionSeed = [prompt: string, options: [string, string, string], answer: number, explanation: string];
type LessonSeed = {
  id: string;
  title: string;
  subtitle: string;
  objective: string;
  focus: string;
  intro: string;
  phrases: [PhraseSeed, PhraseSeed, PhraseSeed, PhraseSeed];
  grammarTitle: string;
  grammar: string;
  examples: [ExampleSeed, ExampleSeed, ExampleSeed, ExampleSeed];
  practice: [QuestionSeed, QuestionSeed, QuestionSeed, QuestionSeed];
  takeaway: string;
};

function makeLesson(seed: LessonSeed): Lesson {
  return {
    id: seed.id,
    slug: seed.id,
    title: seed.title,
    subtitle: seed.subtitle,
    objective: seed.objective,
    duration: 14,
    focus: seed.focus,
    intro: seed.intro,
    phrases: seed.phrases.map(([english, portuguese, note]) => ({ english, portuguese, note })),
    grammar: {
      title: seed.grammarTitle,
      explanation: seed.grammar,
      examples: seed.examples.map(([english, portuguese]) => ({ english, portuguese })),
    },
    practice: seed.practice.map(([prompt, options, answer, explanation]) => ({ prompt, options, answer, explanation })),
    takeaway: seed.takeaway,
  };
}

