function buildModule(id: string, title: string, subtitle: string, seeds: LessonSeed[]): A1Module {
  return { id, title, subtitle, lessons: seeds.map(makeLesson) };
}

const expectedB2Slugs = [
  "claim-and-evidence", "agreeing-with-nuance", "responding-to-counterarguments", "reliable-sources", "structured-debate",
  "technology-at-work", "privacy-and-convenience", "cities-of-the-future", "changing-workplaces", "media-literacy",
  "opening-a-meeting", "clarifying-a-point", "summarizing-decisions", "handling-disagreement", "meeting-simulation",
  "a-clear-professional-email", "polite-follow-ups", "explaining-a-delay", "short-report-structure", "editing-for-tone",
  "define-the-problem", "compare-possible-options", "risks-and-trade-offs", "recommend-with-evidence", "decision-workshop",
  "choose-a-question", "organize-evidence", "write-a-recommendation", "present-to-an-audience", "b2-final-review",
];
const allB2Seeds = [...argumentLessons, ...societyLessons, ...professionalLessons, ...projectLessons];
const lessonBySlug = new Map<string, LessonSeed>();
for (const seed of allB2Seeds) if (expectedB2Slugs.includes(seed.id) && !lessonBySlug.has(seed.id)) lessonBySlug.set(seed.id, seed);
const orderedB2Seeds = expectedB2Slugs.map((slug) => {
  const seed = lessonBySlug.get(slug);
  if (!seed) throw new Error(`Missing B2 lesson content: ${slug}`);
  return seed;
});

export const b2Modules: A1Module[] = [
  buildModule("confident-discussion", "Discussão com confiança", "Defenda posições e compare evidências em temas familiares.", orderedB2Seeds.slice(0, 10)),
  buildModule("professional-communication", "Comunicação profissional", "Escreva e fale com clareza em situações de estudo e trabalho.", orderedB2Seeds.slice(10, 20)),
  buildModule("b2-project-and-review", "Projeto e revisão B2", "Produza uma recomendação fundamentada e apresente-a com segurança.", orderedB2Seeds.slice(20, 30)),
];
